#!/bin/bash
DB="docker exec 1Panel-postgresql-pIe0 psql -U strapi -d strapi -v ON_ERROR_STOP=0"
$DB -c "SELECT table_name, string_agg(column_name, ', ' ORDER BY ordinal_position) AS cols FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('sso_invite_codes','sso_invite_codes_creator_lnk','sso_referral_relations','sso_referral_relations_inviter_lnk','sso_referral_relations_invitee_lnk','sso_referral_relations_invite_code_lnk','sso_invite_usages','sso_invite_usages_user_lnk','sso_invite_usages_invite_code_lnk','activity_referral_rewards','activity_referral_rewards_inviter_lnk','activity_referral_rewards_invitee_lnk','zhao_point_records','zhao_point_records_user_lnk','zhao_point_share_visits','zhao_point_share_visits_inviter_lnk','zhao_user_invites','zhao_user_invites_invited_by_lnk','sso_invite_stats','sso_invite_stats_invite_code_lnk') GROUP BY table_name ORDER BY table_name;"